13	export default class ErrorBoundary extends Component<Props, State> {
14	  constructor(props: Props) {
15	    super(props)
16	    this.state = { hasError: false, error: null }
17	  }
18	
19	  static getDerivedStateFromError(error: Error): State {
20	    return { hasError: true, error }
21	  }
22	
23	  componentDidCatch(error: Error, info: React.ErrorInfo) {
24	    console.error('[ErrorBoundary]', error, info.componentStack)
25	  }
26	
27	  render() {
28	    if (this.state.hasError) {
29	      return (
30	        <div className="flex items-center justify-center min-h-[400px] p-8">
31	          <div className="text-center max-w-md space-y-4">
32	            <div className="mx-auto w-12 h-12 rounded-xl bg-red-muted flex items-center justify-center">
33	              <AlertTriangle className="w-6 h-6 text-red" />
34	            </div>
35	            <h2 className="text-lg font-semibold text-text">Something went wrong</h2>
36	            <p className="text-sm text-text-muted leading-relaxed">
37	              {this.state.error?.message || 'An unexpected error occurred'}
38	            </p>
39	            <button
40	              onClick={() => {
41	                this.setState({ hasError: false, error: null })
42	                window.location.reload()
43	              }}
44	              className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
45	            >
46	              <RefreshCw className="w-4 h-4" />
47	              Reload Page
48	            </button>
49	          </div>
50	        </div>
51	      )
52	    }
53	
54	    return this.props.children
55	  }
56	}
